#!/usr/bin/env python3
"""Compile reviewed Demo inputs, or check their exact generated bytes without writing."""
import argparse
import base64
import ctypes
import json
import os
from pathlib import Path
import shutil
import stat
import sys
import tempfile

from DemoContent import (DATA, OUTPUT_PATHS, WORLD_OUTPUT, WORLD_CONTRACT,
                         ROOT, ContentError, build_outputs, check_outputs, compile_content,
                         require, verify_runtime_files)


def _windows_api():
    require(os.name == "nt", "UnsupportedPlatform", "generation",
            "protected generation requires Windows sharing semantics; parsing and --check remain portable")
    from ctypes import wintypes

    api = ctypes.WinDLL("kernel32", use_last_error=True)
    api.CreateFileW.argtypes = (wintypes.LPCWSTR, wintypes.DWORD, wintypes.DWORD, ctypes.c_void_p,
                               wintypes.DWORD, wintypes.DWORD, wintypes.HANDLE)
    api.CreateFileW.restype = wintypes.HANDLE
    api.SetFileInformationByHandle.argtypes = (wintypes.HANDLE, ctypes.c_int, ctypes.c_void_p, wintypes.DWORD)
    api.SetFileInformationByHandle.restype = wintypes.BOOL
    api.CloseHandle.argtypes = (wintypes.HANDLE,)
    api.CloseHandle.restype = wintypes.BOOL
    return api


class _ProtectedFile:
    """Deny other writers and renames until close; mutate only through this handle."""
    def __init__(self, path, *, writable=False, create=False):
        api = _windows_api()
        import msvcrt

        self.path = Path(path)
        self.created = create
        self.fd = None
        self.delete_pending = False
        access = 0x80000000 | (0x40000000 if writable else 0) | (0x00010000 if create else 0)
        # FILE_SHARE_READ only; no FILE_SHARE_WRITE/DELETE, including during rollback.
        handle = api.CreateFileW(str(self.path), access, 1, None, 1 if create else 3, 0x00200080, None)
        if handle == ctypes.c_void_p(-1).value:
            raise ctypes.WinError(ctypes.get_last_error())
        try:
            self.fd = msvcrt.open_osfhandle(handle, os.O_BINARY | (os.O_RDWR if writable else os.O_RDONLY))
        except OSError as open_error:
            cleanup_errors = []
            if create:
                flag = ctypes.c_int(1)
                if not api.SetFileInformationByHandle(handle, 4, ctypes.byref(flag), ctypes.sizeof(flag)):
                    cleanup_errors.append(str(ctypes.WinError(ctypes.get_last_error())))
            if not api.CloseHandle(handle):
                cleanup_errors.append(str(ctypes.WinError(ctypes.get_last_error())))
            if cleanup_errors:
                raise ContentError("RecoveryRequired", self.path,
                                   f"handle allocation failed: {open_error}; native cleanup failed: "
                                   + "; ".join(cleanup_errors)) from open_error
            raise

    def _same_identity(self):
        try:
            named, held = self.path.stat(follow_symlinks=False), os.fstat(self.fd)
        except OSError as error:
            raise ContentError("PathIdentityChanged", self.path, f"cannot verify held file identity: {error}") from error
        require(stat.S_ISREG(named.st_mode) and os.path.samestat(named, held),
                "PathIdentityChanged", self.path, "named file no longer matches the protected handle")

    def read(self):
        self._same_identity()
        os.lseek(self.fd, 0, os.SEEK_SET)
        chunks = []
        while raw := os.read(self.fd, 1024 * 1024):
            chunks.append(raw)
        self._same_identity()
        return b"".join(chunks)

    def write(self, raw):
        self._same_identity()
        os.lseek(self.fd, 0, os.SEEK_SET)
        offset = 0
        while offset < len(raw):
            count = os.write(self.fd, memoryview(raw)[offset:])
            if count == 0:
                raise OSError(f"Short protected write: {self.path}")
            offset += count
        os.ftruncate(self.fd, len(raw))
        os.fsync(self.fd)

    def mark_delete(self, pending=True):
        require(self.created and self.fd is not None, "ProtectedDelete", self.path,
                "only a still-owned, newly created file can be deleted")
        import msvcrt

        if pending:
            self._same_identity()
        flag = ctypes.c_int(pending)
        if not _windows_api().SetFileInformationByHandle(msvcrt.get_osfhandle(self.fd), 4,
                                                        ctypes.byref(flag), ctypes.sizeof(flag)):
            raise ctypes.WinError(ctypes.get_last_error())
        self.delete_pending = pending

    def close(self):
        if self.fd is not None:
            os.close(self.fd)
            self.fd = None


def _open_output(path, original):
    return _ProtectedFile(path, writable=True, create=original is None)


def _install_output(protected, raw):
    protected.write(raw)


def _restore_output(protected, original):
    if original is None:
        protected.mark_delete()
    else:
        protected.write(original)
        require(protected.read() == original, "RollbackIntegrity", protected.path, "restored bytes differ")


def _remove_lock(protected):
    protected.mark_delete()
    protected.close()


def _remove_transaction(transaction):
    if transaction is not None and transaction.exists():
        shutil.rmtree(transaction)


def _current(path):
    return path.read_bytes() if path.is_file() else None


def _stage(path, raw):
    with path.open("xb") as stream:
        stream.write(raw)
        stream.flush()
        os.fsync(stream.fileno())


def _journal_bytes(before, compilation, phase, failures=(), conflicts=None):
    return (json.dumps({
        "format": "demo-content-recovery-1",
        "pid": os.getpid(),
        "phase": phase,
        "bundle_kind": compilation.bundle_kind,
        "expected_catalog_sha256" if compilation.bundle_kind == "content" else "expected_world_sha256": compilation.digest.hex(),
        "originals": {str(path): None if raw is None else base64.b64encode(raw).decode("ascii")
                      for path, raw in before.items()},
        "expected_outputs": {str(path): base64.b64encode(raw).decode("ascii")
                             for path, raw in compilation.outputs.items()},
        "conflicts": {str(path): None if raw is None else base64.b64encode(raw).decode("ascii")
                      for path, raw in (conflicts or {}).items()},
        "failures": list(failures),
    }, indent=2) + "\n").encode("utf-8")


def _verify_protected(inputs, outputs, compilation, conflicts):
    changed_inputs = []
    for relative, protected in inputs.items():
        try:
            matches = protected.read() == compilation.inputs[relative]
        except ContentError as error:
            if error.code != "PathIdentityChanged":
                raise
            matches = False
        if not matches:
            changed_inputs.append(str(relative))
    for relative, protected in outputs.items():
        try:
            actual = protected.read()
        except ContentError as error:
            if error.code != "PathIdentityChanged":
                raise
            conflicts[relative] = None
            continue
        if actual != compilation.outputs[relative]:
            conflicts[relative] = actual
    require(not changed_inputs, "InputsChanged", ", ".join(changed_inputs),
            "input changed before the protected commit point")
    require(not conflicts, "ConcurrentEdit", ", ".join(str(path) for path in conflicts),
            "output differs at the protected commit point; conflicting bytes will not be overwritten")


def _keep_recovery(lock, lock_path, before, compilation, phase, failures, conflicts):
    created = lock is None or lock.fd is None
    if created:
        lock = _ProtectedFile(lock_path, writable=True, create=True)
    try:
        if lock.delete_pending:
            lock.mark_delete(False)
        lock.write(_journal_bytes(before, compilation, phase, failures, conflicts))
    except (OSError, ContentError):
        if created:
            lock.close()
        raise
    return lock


def _persist_recovery(lock, lock_path, root, before, compilation, phase, failures, conflicts):
    try:
        return _keep_recovery(lock, lock_path, before, compilation, phase, failures, conflicts), lock_path
    except (OSError, ContentError) as error:
        failures.append(f"could not keep the primary recovery journal: {error}")
        scratch = root / "Artifacts" / "DemoContent"
        scratch.mkdir(parents=True, exist_ok=True)
        raw = _journal_bytes(before, compilation, phase, failures, conflicts)
        with tempfile.NamedTemporaryFile(mode="wb", prefix="recovery-", suffix=".json", dir=scratch, delete=False) as stream:
            stream.write(raw)
            stream.flush()
            os.fsync(stream.fileno())
            recovery_path = Path(stream.name)
        require(recovery_path.read_bytes() == raw, "RecoveryPersistenceFailed", recovery_path,
                "recovery record was not persisted intact")
        return lock, recovery_path


def _check_recovery_records(root):
    scratch = Path(root) / "Artifacts" / "DemoContent"
    records = sorted(scratch.glob("recovery-*.json")) if scratch.is_dir() else []
    require(not records, "CompilerBusy", records[0] if records else scratch,
            "unresolved recovery evidence; identical outputs do not bypass it")


def write_outputs(root, compilation):
    """Commit under Windows write/delete exclusion, with manifest written last.

    All input/output handles stay protected through final verification and cleanup.
    Existing files are written in place through those handles, never path-replaced.
    Readers still need root/child verification: this is not a multi-file OS transaction.
    """
    root = Path(root).resolve()
    _check_recovery_records(root)
    outputs = compilation.outputs
    bundles = {"content": OUTPUT_PATHS, "world": (WORLD_OUTPUT, WORLD_CONTRACT)}
    require(compilation.bundle_kind in bundles, "OutputShape", root, "unknown producer bundle")
    output_paths = bundles[compilation.bundle_kind]
    require(set(outputs) == set(output_paths) and not set(outputs).intersection(compilation.inputs)
            and all(type(raw) is bytes for raw in outputs.values()),
            "OutputShape", root, "unexpected output set")
    for relative in (*outputs, *compilation.inputs):
        resolved = (root / relative).resolve()
        require(resolved.is_relative_to(root), "OutputPath", relative, "path escapes the worktree")
        require(resolved == root / relative, "OutputPath", relative, "generated paths must not traverse symbolic links")
    output_dir = root / DATA
    output_dir.mkdir(parents=True, exist_ok=True)
    lock_path = output_dir / ".compile.lock"
    try:
        lock = _ProtectedFile(lock_path, writable=True, create=True)
    except OSError as error:
        if lock_path.exists() or getattr(error, "winerror", None) in (80, 183):
            raise ContentError("CompilerBusy", lock_path,
                               "active or unresolved recovery journal; identical outputs do not bypass it") from error
        raise
    transaction = None
    inputs, protected_outputs = {}, {}
    touched = set()
    before = {}
    conflicts = {}
    failure = None
    cleanup_started = False
    committed = False
    recovery = False
    try:
        # The snapshots are only expectations. Compare them again after acquiring
        # handles that prohibit the editor-save races a path comparison cannot stop.
        before = {relative: _current(root / relative) for relative in output_paths}
        lock.write(_journal_bytes(before, compilation, "acquiring"))
        for relative, original in compilation.inputs.items():
            protected = _ProtectedFile(root / relative)
            inputs[relative] = protected
            require(protected.read() == original, "InputsChanged", relative,
                    "input changed before protection was acquired")
        for relative in output_paths:
            target = root / relative
            require(not target.exists() or target.is_file(), "OutputPath", relative, "target is not a regular file")
            target.parent.mkdir(parents=True, exist_ok=True)
            protected = _open_output(target, before[relative])
            protected_outputs[relative] = protected
            actual = None if protected.created else protected.read()
            require(actual == before[relative], "ConcurrentEdit", relative,
                    "output changed before protection was acquired; external bytes were preserved")

        changed = [path for path in output_paths if before[path] != outputs[path]]
        if changed:
            scratch = root / "Artifacts" / "DemoContent"
            scratch.mkdir(parents=True, exist_ok=True)
            transaction = Path(tempfile.mkdtemp(prefix="transaction-", dir=scratch))
            # The protected, fsynced journal keeps EVERY original even if backup
            # directory cleanup deletes some/all old-* files and then fails.
            lock.write(_journal_bytes(before, compilation, "prepared"))
            for index, relative in enumerate(output_paths):
                _stage(transaction / f"new-{index}", outputs[relative])
                if before[relative] is not None:
                    _stage(transaction / f"old-{index}", before[relative])
            for relative in changed:
                touched.add(relative)
                _install_output(protected_outputs[relative], outputs[relative])
        _verify_protected(inputs, protected_outputs, compilation, conflicts)
        cleanup_started = True
        _remove_transaction(transaction)
        _verify_protected(inputs, protected_outputs, compilation, conflicts)
        _remove_lock(lock)
        _verify_protected(inputs, protected_outputs, compilation, conflicts)
        committed = True
    except (OSError, ContentError) as error:
        failure = error
        rollback_failures = []
        for relative in reversed(output_paths):
            protected = protected_outputs.get(relative)
            if protected is None or relative in conflicts:
                continue
            if relative not in touched and not protected.created:
                continue
            try:
                _restore_output(protected, before[relative])
            except (OSError, ContentError) as rollback_error:
                rollback_failures.append(str(rollback_error))
        recovery = (cleanup_started or bool(rollback_failures) or bool(conflicts)
                    or (isinstance(error, ContentError) and error.code == "RecoveryRequired"))
        if not recovery:
            try:
                _remove_transaction(transaction)
                _remove_lock(lock)
            except (OSError, ContentError) as cleanup_error:
                rollback_failures.append(str(cleanup_error))
                recovery = True
        if recovery:
            failures = [str(error), *rollback_failures]
            try:
                lock, recovery_path = _persist_recovery(
                    lock, lock_path, root, before, compilation,
                    "recovery_required" if rollback_failures or conflicts else "rolled_back_cleanup_failed",
                    failures, conflicts)
            except (OSError, ContentError) as journal_error:
                failures.append(f"could not persist recovery evidence: {journal_error}")
                failure = ContentError("RecoveryPersistenceFailed", lock_path, "; ".join(failures))
            else:
                failure = ContentError("RecoveryRequired", recovery_path,
                                       "original bytes are retained in this recovery record; " + "; ".join(failures))
    finally:
        close_failures = []
        for protected in (*reversed(tuple(protected_outputs.values())), *reversed(tuple(inputs.values()))):
            try:
                protected.close()
            except OSError as error:
                close_failures.append(f"{protected.path}: {error}")
                try:
                    protected.close()
                except OSError as retry_error:
                    close_failures.append(f"{protected.path}: close retry failed: {retry_error}")
        if close_failures:
            failures = ([str(failure)] if failure is not None else []) + close_failures
            try:
                lock, recovery_path = _persist_recovery(
                    lock, lock_path, root, before, compilation,
                    "committed_handle_cleanup_failed" if committed else "handle_cleanup_failed",
                    failures, conflicts)
            except (OSError, ContentError) as journal_error:
                failures.append(f"could not persist recovery evidence: {journal_error}")
                failure = ContentError("RecoveryPersistenceFailed", lock_path, "; ".join(failures))
            else:
                failure = ContentError("RecoveryRequired", recovery_path,
                                       f"committed={committed}; protected handle cleanup failed; " + "; ".join(failures))
        try:
            lock.close()
        except OSError as error:
            try:
                lock.close()
            except OSError as retry_error:
                close_failures.append(f"journal close retry failed: {retry_error}")
            failure = ContentError("RecoveryRequired", lock_path,
                                   f"committed={committed}; journal handle close failed: {error}; "
                                   f"prior failure: {failure}; {'; '.join(close_failures)}")
    if failure is not None:
        raise failure


def synchronize(root=ROOT, check=False):
    _check_recovery_records(root)
    compilation = compile_content(root)
    if check:
        require(not (Path(root) / DATA / ".compile.lock").exists(), "CompilerBusy", DATA,
                "active or unresolved generation journal; resolve it before checking outputs")
        check_outputs(root, compilation.outputs)
    else:
        write_outputs(root, compilation)
    return compilation


def main(argv=None, root=ROOT):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="compare all outputs; never generate or repair files")
    args = parser.parse_args(argv)
    try:
        result = synchronize(root, check=args.check)
    except (OSError, ValueError) as error:
        print(f"FAIL Demo content: {error}", file=sys.stderr)
        return 2
    print(f"PASS Demo content {'check' if args.check else 'generation'}: root SHA256 {result.digest.hex()}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
